    def __init__(self, name: str, excluded_files: List[str]):
        self.name = name
        self.excluded_files = excluded_files
        self.debugger_command_classes = []

        # Import all submodules from the directory named name
        for filename in os.listdir(name + 'sub'):
            if filename.endswith('.py') and filename not in excluded_files:
                module_name = filename[:-3]
                module = importlib.import_module(name + 'sub.' + module_name)

                # Scan for class names in the module
                for attribute_name in dir(module):
                    attribute = getattr(module, attribute_name)
                    if isinstance(attribute, type) and issubclass(attribute, DebuggerCommand):
