class ExprNode:
    def __init__(self, value, left=None, right=None):
        self.value = value
        self.left = left
        self.right = right

    def __repr__(self):
        return f'{self.value}'

    def evaluate(self):
        if self.left is None and self.right is None:
            return self.value
        else:
            return self.value(self.left.evaluate(), self.right.evaluate())

def random_expr(depth, vlist, ops):
    if depth == 1:
        return ExprNode(choice(vlist))
    else:
        op = choice(ops)
        return ExprNode(op, random_expr(depth-1, vlist, ops), random_expr(depth-1, vlist, ops))

