    search_index = content.searchIndex if content else None
    if search_index:
        vm = search_index.FindByDnsName(datacenter=datacenter, dnsName=name, vmSearch=True)
        if vm:
            vm_properties_instance = content.propertyCollector if content else None
            if vm_properties_instance:
                property_spec = vim.PropertySpec(
                    type=vim.VirtualMachine,
                    pathSet=vm_properties,
                )
                object_spec = vim.ObjectSpec(
                    obj=vm,
                    skip=False,
                    selectSet=traversal_spec,
                )
                property_filter_spec = vim.PropertyFilterSpec(
                    objectSet=[object_spec],
                    propSet=[property_spec],
                )
                return vm_properties_instance.RetrieveProperties(
                    propFilter=[property_filter_spec],
                )
    return None

