def sample_conditional(mean, cov, M, num_samples=None):
    if M.isprior:
        if num_samples is None:
            return M.sample_prior().reshape((-1,) + M.pshape)
        else:
            return M.sample_prior(num_samples).reshape((num_samples, -1) + M.pshape)
    elif isinstance(M, KmeansModel) and isinstance(M.cond_ds, CondData):
        return M.sample_cond_kmeans(mean, cov, num_samples)
    else:
        if num_samples is None:
            num_samples = 1
        eps = np.random.randn(num_samples, cov.shape[0], cov.shape[0])
        L = np.linalg.cholesky(cov)
        samples = np.zeros((num_samples, cov.shape[0], mean.shape[-1]))
        for i in range(num_samples):
            samples[i] = mean.T + L @ eps[i].T
        samples = samples.T
        return samples, mean, cov

