def traverse_options(obj, opt_type, specs, opts, keyfn=None):
    """
    Traverses the supplied object getting all options in opts for
    the specified opt_type and specs. Also takes into account the
    plotting class defaults for plot options. If a keyfn is
    supplied the returned options will be grouped by the returned
    keys.
    """
    options = []
    if isinstance(obj, dict):
        for k, v in obj.items():
            if k == opt_type and all(item in v.items() for item in specs.items()):
                options.append(v)
            elif isinstance(v, (dict, list)):
                options.extend(traverse_options(v, opt_type, specs, opts))

    elif isinstance(obj, list):
        for item in obj:
            options.extend(traverse_options(item, opt_type, specs, opts))

    if opts:
        options.extend(opts.get(opt_type, {}).values())

    if keyfn:
        return {keyfn(option): option for option in options}
    else:
        return options

