from yaml import SafeLoader

def load_yaml_with_include(filename):
    class IncludeLoader(SafeLoader):
        # Define a custom tag handler to handle `!include` tag
        def include(self, node):
            # Extract the path from the tag value
            path = os.path.join(os.path.dirname(self.name), self.construct_scalar(node))
            # Load the included file and return its contents
            with open(path, 'r') as f:
                return yaml.load(f, IncludeLoader)
    # Set the Loader to use our custom IncludeLoader
    IncludeLoader.add_constructor('!include', IncludeLoader.include)
    with open(filename, 'r') as f:
        return yaml.load(f, IncludeLoader)

