from werkzeug.formparser import MultiPartParser


def multipart_parser_middleware(request, next_app):
    if request.method in ['POST', 'PUT', 'PATCH', 'DELETE']:
        content_type = request.content_type.lower()
        if content_type.startswith('multipart/'):
            form, files = MultiPartParser().parse(request.environ)
            request.multipart_params = {}
            for key, value in form.items():
                if key in request.multipart_params:
                    if isinstance(request.multipart_params[key], list):
                        request.multipart_params[key].append(value)
                    else:
                        request.multipart_params[key] = [request.multipart_params[key], value]
                else:
                    request.multipart_params[key] = value
            request.params = MultiDict(request.params)
            request.params.update(request.multipart_params)
    return next_app(request)

