import importlib.util


def find_decorated_modules(path, decorator_module, decorator_name):
    decorated_modules = []
    decorator_spec = importlib.util.find_spec(decorator_module)
    decorator = None
    if decorator_spec is not None:
        decorator = importlib.util.module_from_spec(decorator_spec)
        decorator_spec.loader.exec_module(decorator)

    for root, dirs, files in os.walk(path):
        for file in files:
            if file.endswith('.py'):
                module_path = os.path.join(root, file)
                module_spec = importlib.util.spec_from_file_location(file[:-3], module_path)
                module = importlib.util.module_from_spec(module_spec)
                module_spec.loader.exec_module(module)

                for name, obj in module.__dict__.items():
                    if callable(obj) and decorator is not None and hasattr(obj, '__wrapped__'):
                        if decorator_name in obj.__wrapped__.__qualname__:
                            decorated_modules.append(module.__name__)
                            break
    return decorated_modules

