class ExcelSheet:
    def __init__(self, sheet_node, shared_strings):
        self.sheet_data_node = sheet_node.find('{http://schemas.openxmlformats.org/spreadsheetml/2006/main}sheetData')
        self.shared_strings = shared_strings
        
    def GetCellValue(self, row, col):
        cell_node = self.sheet_data_node.find('{http://schemas.openxmlformats.org/spreadsheetml/2006/main}row[@r="{}"]/c[@r="{}{}"]'.format(row, chr(ord('A')+col-1), row))
        if cell_node is not None and 't' in cell_node.attrib and cell_node.attrib['t'] == 's':
            return self.shared_strings[int(cell_node.find('{http://schemas.openxmlformats.org/spreadsheetml/2006/main}v').text)].text
        elif cell_node is not None:
            return cell_node.find('{http://schemas.openxmlformats.org/spreadsheetml/2006/main}v').text
        else:
            return None
    
class ExcelXMLFile:
    def __init__(self, path):
        self.tree = ET.parse(path)
        self.root = self.tree.getroot()
        self.shared_strings = self.LoadSharedStrings()
        
    def LoadSharedStrings(self):
        shared_strings_node = self.root.find('{http://schemas.openxmlformats.org/spreadsheetml/2006/main}sst')
        if shared_strings_node is None:
            return None
        shared_strings = [child for child in shared_strings_node]
        return shared_strings
    
    def GetWorksheets(self, index=None):
        worksheets = self.root.findall('{http://schemas.openxmlformats.org/spreadsheetml/2006/main}sheets/{http://schemas.openxmlformats.org/spreadsheetml/2006/main}sheet')
        if worksheets is None:
            return None
        if index is not None:
            worksheet = worksheets[index]
            sheet_id = worksheet.attrib['{http://schemas.openxmlformats.org/officeDocument/2006/relationships}id']
            sheet_node = self.root.find('{http://schemas.openxmlformats.org/spreadsheetml/2006/main}sheet[@{http://schemas.openxmlformats.org/officeDocument/2006/relationships}id="{}"]'.format(sheet_id))
            return ExcelSheet(sheet_node, self.shared_strings)
        else:
            return [ExcelSheet(sheet, self.shared_strings) for sheet in worksheets]

def ParseExcelXMLFile(path):
    return ExcelXMLFile(path)

