            raise SerializationException("Error loading class, module info not provided and " + class_name + " not present in sys.modules")
        return sys.modules[class_name]
    module_name, class_name = class_name.rsplit(".", 1)
    try:
        module = import_module(module_name)
    except ImportError:
        raise SerializationException('Error loading class ' + class_name + ' from module ' + module_name)

    try:
        return getattr(module, class_name)
    except AttributeError:
        raise SerializationException('Module "{module_name}" does not define a "{class_name}" attribute/class')

import subprocess

def get_queue_nodes(queue_name):
    p = subprocess.Popen(['qstat', '-Qf', queue_name], stdout=subprocess.PIPE, stderr=subprocess.PIPE)
    output, error = p.communicate()
    acl_hosts = None
    for line in output.decode().split('\n'):
        line = line.strip()
        if line.startswith('acl_hosts'):
            acl_hosts = line.split('=')[1].strip()
            break

    nodes = set()
    if acl_hosts:
        for host in acl_hosts.split():
            if '[' in host:
                node_names = host.split('[')[1].split(']')[0].split(',')
                for name in node_names:
                    if '-' in name:
                        start, end = name.split('-')
                        nodes.update(set(range(int(start), int(end) + 1)))
                    else:
                        nodes.add(int(name))
            else:
                nodes.add(int(host))

    p = subprocess.Popen(['pbsnodes'], stdout=subprocess.PIPE, stderr=subprocess.PIPE)
    output, error = p.communicate()
    names = set()
    for line in output.decode().split('\n'):
        line = line.strip()
        if line.startswith('name = '):
            names.add(line.split('=')[1].strip().split('.')[0])

    return sorted([name for name in names if int(name.split('-')[-1]) in nodes])

