def decode_map(encoded_map):
    result = {}
    i = 0
    while i < len(encoded_map):
        count = _read_long(encoded_map[i:])
        i += _encoded_length(count)
        if count == 0:
            break
        elif count > 0:
            for _ in range(count):
                key = _read_object(encoded_map[i:])
                i += _encoded_length(key)
                value = _read_object(encoded_map[i:])
                i += _encoded_length(value)
                result[key] = value
        else:
            count = -count
            block_size = _read_long(encoded_map[i:])
            i += _encoded_length(block_size)
            for _ in range(count):
                key = _read_object(encoded_map[i:])
                i += _encoded_length(key)
                value = _read_object(encoded_map[i:i + block_size])
                i += block_size
                result[key] = value
    return result

def _read_long(encoded):
    i = 0
    while encoded[i] & 0x80:
        i += 1
    i += 1
    return _decode_varint(encoded[:i])

def _decode_varint(encoded):
    result = 0
    shift = 0
    for b in encoded:
        result |= (b & 0x7F) << shift
        if not b & 0x80:
            break
        shift += 7
    return result

def _encoded_length(value):
    if value >= 0:
        return 1 + (value.bit_length() + 6) // 7
    else:
        return 10

def _read_object(encoded):
    encoded_type = encoded[0]
    value = encoded[1:]
    if encoded_type == 0:
        return None
    elif encoded_type == 1:
        return _decode_varint(value)
    elif encoded_type == 2:
        return _decode_double(value)
    elif encoded_type == 3:
        return value.decode("UTF-8")
    elif encoded_type == 4:
        return decode_map(value)
    elif encoded_type == 5:
        return decode_array(value)
    elif encoded_type == 6:
        return _decode_boolean(value)
    elif encoded_type == 7:
        return _decode_bytes(value)
    else:
        raise ValueError(f"Unknown encoded type: {encoded_type}")

