def major_head_loss_rectangular_channel(width, height, velocity, density, viscosity, length):
    reynolds_number = velocity * height / viscosity
    friction_factor = 0.0
    if reynolds_number > 0:
        if reynolds_number < 2300:
            friction_factor = 64 / reynolds_number
        else:
            # Use the Colebrook-White equation to calculate friction factor
            k = 0.00001
            friction_factor = 0.08 # Initial estimate for f
            while True:
                next_friction_factor = (-2 * math.log10((k/3.7) + (2.51/(reynolds_number * math.sqrt(friction_factor)))))**(-2)
                if abs(next_friction_factor - friction_factor) < 0.00001:
                    break
                friction_factor = next_friction_factor

    velocity_head = (velocity ** 2) / (2 * 9.81)
    friction_head_loss = friction_factor * length * (velocity ** 2) / (2 * height)
