def generate_json_schema(model):
    """
    Generate JSON Schema representation of a Biolink Model

    Parameters
    ----------
    model: dict
        A dictionary containing biolink model and its attributes

    Returns
    -------
    json_schema: dict
        A JSON Schema representation of a Biolink Model
    """
    model_properties = model.get('properties')
    biolink_types = ['category', 'function', 'slot', 'typedef']
    json_schema = {'$schema': 'http://json-schema.org/draft-07/schema#',
                   'type': 'object',
                   'properties': {}}
    for biolink_type in biolink_types:
        current_type_properties = model_properties.get(biolink_type)
        if current_type_properties:
            json_schema['properties'][biolink_type] = {'type': 'object',
                                                       'properties': {}}
            for property_name, property_attributes in current_type_properties.items():
                required = property_attributes.get('required', False)
                property_type = property_attributes.get('type')
                property_description = property_attributes.get('description')
                if property_type == 'object':
                    property_json_schema = generate_json_schema(property_attributes)
                else:
                    property_json_schema = {'type': property_type}
                if required:
                    json_schema['properties'][biolink_type]['properties'][property_name] = {'$ref': '#/components/schemas/' + property_name}
                    json_schema['components'] = {'schemas': {property_name: property_json_schema}}
                else:
                    json_schema['properties'][biolink_type]['properties'][property_name] = property_json_schema
                if property_description:
                    json_schema['properties'][biolink_type]['properties'][property_name]['description'] = property_description
    return json_schema

